mapper.select:
SELECT DISTINCT FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, MF.FEE_NAME feeName, FFCRD.LEV lev, FFCRD.COEFFICIENT coefficient, FFCRD.SPREAD_RATE*100 spreadRate, FFCRD.CHARGE_RATIO*100 chargeRatio, FFCRD.EFF_DATE effDate, FCI.CASH_ID cashId, FP.FINPROD_ID finprodId, '0.0' intRate, FFCR.BASE_RULE baseRule, PLP.Prod_Style prodStyle,
IFFCR.SEND_STATUS sendStatus, IFFCR.SEND_REMARK sendRemark ,FPA.INVESTMENT_CYCLE investmentCycle FROM FIN_PRODUCT FP LEFT JOIN PRD_LAYER_PARAM PLP ON PLP.FINPROD_ID =FP.FINPROD_ID, FIN_BASE_RULE_INFO FBRI, FIN_FLOAT_CALC_RULE FFCR, FIN_FLOAT_CALC_RULE_DETAIL FFCRD
LEFT JOIN INF_FIN_FLOAT_CALC_RULE IFFCR ON FFCRD.CASH_ID =IFFCR.CASH_ID AND FFCRD.EFF_DATE =IFFCR.EFF_DATE,
MST_FEEINFO MF, FIN_CASH_INFO FCI, fin_product_add FPA, PTL_PORTFOLIO_AUTHORITY PPA WHERE FP.FINPROD_ID = FCI.FINPROD_ID AND FP.FINPROD_ID = FBRI.FINPROD_ID AND FP.FINPROD_TYPE = #{finprodType2} AND FP.PROFIT_TYPE IN
#{item,jdbcType=VARCHAR}
AND FCI.FEE_ID = MF.FEE_ID AND FCI.CASH_ID = FFCRD.CASH_ID AND FCI.CASH_TYPE_2 = #{cashType2} AND FFCR.CASH_ID = FFCRD.CASH_ID AND FFCR.EFF_DATE = FFCRD.EFF_DATE AND FPA.FINPROD_ID = FP.FINPROD_ID AND FPA.PORTFOLIO_ID = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
AND FCI.BRANCH = 0
AND FPA.Issue_Status=#{issueStatus}
AND( FP.FINPROD_ID IN(
#{item}
) OR FP.P_FINPROD_ID IN(
#{item}
) )
AND FP.FINPROD_ID IN(
#{item}
)
AND DATE_FORMAT(FFCRD.EFF_DATE,'%Y-%m-%d') >= #{effDateStart}
AND DATE_FORMAT(FFCRD.EFF_DATE,'%Y-%m-%d') <= #{effDateEnd}
#{key,jdbcType=VARCHAR}
ORDER BY FP.FINPROD_ID ASC, FFCRD.EFF_DATE DESC,FFCRD.LEV ASC

SELECT A.INDEX_ID indexId, A.INDEX_SOURCE indexSource, A.BASE_RULE_ID baseRuleId FROM FIN_BASE_RULE_INFO A WHERE A.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND DATE_FORMAT(A.EFF_DATE,'%Y-%m-%d') <= #{effDate}
AND A.Base_Rule_Type = #{BASE_RULE_TYPE_02}
ORDER BY A.EFF_DATE DESC

SELECT DISTINCT FP.FINPROD_ID id, CONCAT_WS('',FP.FINPROD_MARKET_ID ,':', FP.FINPROD_ABBR) text, CONCAT_WS('',FP.FINPROD_MARKET_ID , ',', FPA.DEAL_MODE) object, FIN_PRODUCT.VDATE col FROM FIN_PRODUCT FP, PTL_MANAGE_OBJ PMO, PTL_PORTFOLIO_AUTHORITY PPA, FIN_PRODUCT_ADD FPA
FP.FINPROD_TYPE2 = #{finprodType2} AND PMO.MANAGE_OBJ_ID = FP.FINPROD_ID AND PMO.PORTFOLIO_ID = PPA.PORTFOLIO_ID AND FPA.FINPROD_ID = FP.FINPROD_ID
AND FPA.Issue_Status=#{issueStatus}
AND PPA.USER_ID = #{userId}
AND FP.PROFIT_TYPE IN(
#{item}
)
AND (FP.FINPROD_ID like concat('%',#{search,jdbcType=VARCHAR},'%') OR FP.FINPROD_ABBR like concat('%',#{search,jdbcType=VARCHAR},'%'))
AND FP.FINPROD_ID = #{initValue}

SELECT FIN_FLOAT_CALC_RULE_DETAIL.LEV lev, FIN_FLOAT_CALC_RULE_DETAIL.SPREAD_RATE*100 spreadRate, FIN_FLOAT_CALC_RULE_DETAIL.BASE_RULE_ID baseRuleId, FIN_FLOAT_CALC_RULE_DETAIL.COEFFICIENT coefficient, FIN_FLOAT_CALC_RULE_DETAIL.CHARGE_RATIO*100 chargeRatio FROM FIN_FLOAT_CALC_RULE_DETAIL
FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
AND FIN_FLOAT_CALC_RULE_DETAIL.LEV = #{lev}
AND DATE_FORMAT(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'%Y-%m-%d') = #{effDate}
AND FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = (select max(eff_date) from FIN_FLOAT_CALC_RULE_DETAIL where DATE_FORMAT(EFF_DATE,'%Y-%m-%d')<=#{SESSION_SYS_DATE} and cash_id=#{cashId})
AND DATE_FORMAT(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'%Y-%m-%d') = #{effDate}
ORDER BY FIN_FLOAT_CALC_RULE_DETAIL.LEV ASC

SELECT SUM(A.count) count
FROM
(SELECT
COUNT(*) as count
FROM
FIN_CASH_INFO FCI,
FIN_FLOAT_COUNTING_RULE FFCRU
WHERE
FCI.FINPROD_ID = 	#{finprodId}
AND FCI.CASH_ID =	FFCRU.CASH_ID
AND FCI.CASH_TYPE_2 = #{cashType2}
 AND DATE_FORMAT(FFCRU.EFF_DATE,'%Y-%m-%d')  > #{effDate} 
UNION ALL
SELECT
COUNT(*) as count
FROM
FIN_CASH_INFO FCI,
FIN_CASH_PAY_RULE FCPR

	FCI.FINPROD_ID = 	#{finprodId}
	AND FCI.CASH_ID =	FCPR.CASH_ID
	AND	FCI.CASH_TYPE_2 = #{cashType2}
	 AND DATE_FORMAT(FCPR.EFF_DATE,'%Y-%m-%d')  > #{effDate} 
)A

SELECT FP.FINPROD_ABBR finprodAbbr, FP.FINPROD_ID finprodId, MF.FEE_NAME feeName, MF.FEE_ID feeId, MF.BASIC_BILL basicBill, MF.BASIS basis, FCI.CASH_ID cashId, FFCR.AST_VDATE_TYPE astVdateType, FFCRU.F_ACCR_DATE fAccrDate, FFCR.EFF_DATE effDate,
FFCR.BASE_RULE baseRule, FFCR.REMARK remark,
FFCRU.E_ACCR_DATE eAccrDate, FFCRU.ACCR_TYPE accrType, FFCRU.INTERVAL_RULE intervalRule, FFCRU.ACCR_TDAY_RULE accrTdayRule, FFCRU.F_ACCR_END_DATE fAccrEndDate, FCPR.PAY_CYCLE payCycle, FCPR.FIRST_PAY_DATE firstPayDate, FCPR.END_TDAY_RULE endTdayRule, FCPR.PAY_TDAY_RULE payTdayRule, FP.P_FINPROD_ID pFinprodId ,FP.FINPROD_market_ID finprodMarketId ,PLP.Prod_Style prodStyle ,FPA.DEAL_MODE dealMode FROM FIN_PRODUCT FP LEFT JOIN PRD_LAYER_PARAM PLP ON PLP.FINPROD_ID =FP.FINPROD_ID, MST_FEEINFO MF, FIN_FLOAT_CALC_RULE FFCR, FIN_FLOAT_COUNTING_RULE FFCRU, FIN_CASH_INFO FCI,
FIN_CASH_PAY_RULE FCPR, FIN_PRODUCT_ADD FPA
FP.FINPROD_ID = #{finprodId} AND FCI.CASH_TYPE_2 = #{cashType2} AND FCI.CASH_ID =FFCR.CASH_ID AND FCI.CASH_ID = FFCRU.CASH_ID AND FCI.FINPROD_ID = FP.FINPROD_ID AND FCPR.EFF_DATE=FFCR.EFF_DATE AND FCI.CASH_ID = FCPR.CASH_ID
AND FPA.FINPROD_ID = FP.FINPROD_ID
AND FCI.CASH_ID = FFCRU.CASH_ID AND FFCRU.EFF_DATE=FFCR.EFF_DATE AND FCI.FEE_ID = MF.FEE_ID
AND FFCR.CASH_ID = #{cashId}
AND FPA.INVESTMENT_CYCLE = #{investmentCycle}
AND DATE_FORMAT(FFCR.EFF_DATE,'%Y-%m-%d') = #{effDate}

SELECT BASE_RULE_ID baseRuleId, EFF_DATE effDate, RATE_TYPE rateType, RATE*100 rate, INDEX_ID indexId, INDEX_SOURCE indexSource, COEFFICIENT coefficient, SPREAD_RATE*100 spreadRate, RESET_TYPE resetType, FINPROD_ID finprodId, BRANCH branch, REMARK remark, BASE_RULE_TYPE baseRuleType, PUBLISH_TYPE publishType, RATE_LOWER rateLower, RATE_LIMIT rateLimit FROM FIN_BASE_RULE_INFO where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and EFF_DATE = STR_TO_DATE(#{effDate,jdbcType=VARCHAR},'%Y-%m-%d')
and EFF_DATE = (SELECT max(EFF_DATE) FROM FIN_BASE_RULE_INFO where FINPROD_ID =#{finprodId,jdbcType=VARCHAR} and BASE_RULE_TYPE =#{baseRuleType02,jdbcType=VARCHAR} and EFF_DATE <=STR_TO_DATE(#{sysFloatDate,jdbcType=VARCHAR},'%Y-%m-%d') and BRANCH = 0)
and BASE_RULE_TYPE = #{baseRuleType02,jdbcType=VARCHAR}
and BRANCH = 0
